void rtdb_init(tRTDB_INITDATA_STR* RtdbCfg)
{
    if (true == rtdb_s_moduleInit_tB)
    {
        errh_reportError(ERRH_NOTIF, MODULE_RTDB, 0, RTDB_API_INIT_U32, ERRH_MODULE_ALREADY_INIT);
    }
    else if (NULL == RtdbCfg)
    {
        errh_reportError(ERRH_ERROR_CRITICAL, MODULE_RTDB, 0, RTDB_API_INIT_U32, ERRH_POINTER_IS_NULL);
    }
    else
    {
        db_mutex = xSemaphoreCreateMutex();
        canm_rtdb_init();
        dimh_rtdb_init();
        diom_rtdb_init();
        mbcm_rtdb_init();
        rtdb_s_moduleInit_tB = true;
    }
}
